export function SortHeading({
  field,
  label,
  sort,
  onSort,
}: {
  field: DriveSort["field"];
  label: string;
  sort: DriveSort;
  onSort: (sort: DriveSort) => void;
}) {
  const active = sort.field === field;
  const Icon = active ? (sort.direction === "asc" ? ArrowUpIcon : ArrowDownIcon) : ArrowUpDownIcon;
  return (
    <th
      scope="col"
      aria-sort={active ? (sort.direction === "asc" ? "ascending" : "descending") : "none"}
      className={tableHeaderClass}
    >
      <button
        type="button"
        className={cn(buttonClass, "-ml-3 whitespace-nowrap")}
        onClick={() =>
          onSort({ field, direction: active && sort.direction === "asc" ? "desc" : "asc" })
        }
      >
        {label}
        <Icon aria-hidden="true" />
      </button>
    </th>
  );
}

export function DriveModified({
  value,
  locale,
  fallback,
}: {
  value?: string;
  locale?: string;
  fallback: string;
}) {
  if (!value || !Number.isFinite(Date.parse(value))) return fallback;
  return (
    <time dateTime={value}>
      {new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
        new Date(value),
      )}
    </time>
  );
}

export function DriveSize({
  value,
  locale,
  fallback,
}: {
  value?: number;
  locale?: string;
  fallback: string;
}) {
  if (value === undefined || !Number.isFinite(value) || value < 0) return fallback;
  const [divisor, unit]: [number, string] =
    value >= 1_000_000_000
      ? [1_000_000_000, "gigabyte"]
      : value >= 1_000_000
        ? [1_000_000, "megabyte"]
        : value >= 1_000
          ? [1_000, "kilobyte"]
          : [1, "byte"];
  return new Intl.NumberFormat(locale, { style: "unit", unit, maximumFractionDigits: 1 }).format(
    value / divisor,
  );
}

export function DriveOwner({ owner, fallback }: { owner?: DriveSpace["owner"]; fallback: string }) {
  if (!owner) return fallback;
  return (
    <span className="flex items-center gap-2">
      {owner.image && (
        <Image
          src={owner.image}
          alt=""
          width={28}
          height={28}
          className="size-7 shrink-0 rounded-full object-cover"
        />
      )}
      <span className="max-w-48 truncate" title={owner.name}>
        {owner.name}
      </span>
    </span>
  );
}

export function DriveFeedback({ message, error = false }: { message?: string; error?: boolean }) {
  return message ? (
    <p
      role={error ? "alert" : "status"}
      className={cn("text-sm", error ? "text-destructive" : "text-muted-foreground")}
    >
      {message}
    </p>
  ) : null;
}

export function DriveToasts({
  labels,
  queue,
}: {
  labels: DriveLabels;
  queue: ReturnType<typeof useUploads>;
}) {
  const { add, close } = Toast.useToastManager<ActionToastData>();
  const id = `factory-drive-upload-toast-${useId()}`;
  const currentQueue = useRef(queue);
  useEffect(() => {
    currentQueue.current = queue;
  }, [queue]);
  const { uploads, dismiss } = queue;
  const finished = uploads.every((upload) => ["done", "cancelled"].includes(upload.state));
  const loading = uploads.some((upload) =>
    ["queued", "uploading", "finishing", "cancelling"].includes(upload.state),
  );
  useEffect(() => () => close(id), [close, id]);
  useEffect(() => {
    if (!uploads.length) {
      close(id);
      return;
    }
    add({
      id,
      type: loading ? "loading" : finished ? "success" : "error",
      title: labels.uploads,
      data: {
        closeLabel: labels.close,
        dismissible: finished,
        content: (
          <ul className="ms-8 max-h-[50dvh] space-y-4 overflow-y-auto">
            {uploads.map((upload) => (
              <li key={upload.id} className="space-y-2">
                <span className="block text-sm break-all">
                  {upload.relativePath ?? upload.file.name}
                </span>
                <progress
                  className={cn(
                    "h-2 w-full appearance-none bg-muted [&::-moz-progress-bar]:bg-current [&::-webkit-progress-bar]:bg-muted [&::-webkit-progress-value]:bg-current",
                    upload.state === "done"
                      ? "text-status-success-foreground"
                      : upload.state === "failed" || upload.state === "cancelFailed"
                        ? "text-destructive"
                        : upload.state === "cancelled"
                          ? "text-status-canceled-foreground"
                          : "text-status-pending-foreground",
                  )}
                  max={100}
                  value={upload.progress}
                  aria-label={labels.progress(upload.file.name)}
                />
                {upload.error !== undefined && (
                  <DriveFeedback message={messageFor(upload.error, labels)} error />
                )}
                <ActionToastFooter
                  status={
                    <DriveFeedback
                      message={labels[upload.state]}
                      error={upload.state === "failed" || upload.state === "cancelFailed"}
                    />
                  }
                  actions={
                    <>
                      {["failed", "cancelFailed"].includes(upload.state) && (
                        <button
                          className={actionToastButtonClass}
                          onClick={() => currentQueue.current.retry(upload.id)}
                        >
                          <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
                          {labels.retry}
                        </button>
                      )}
                      {["queued", "uploading", "failed"].includes(upload.state) && (
                        <button
                          className={actionToastButtonClass}
                          onClick={() => currentQueue.current.cancel(upload.id)}
                        >
                          {labels.cancel}
                        </button>
                      )}
                      {["done", "cancelled"].includes(upload.state) && (
                        <button
                          className={actionToastButtonClass}
                          onClick={() => dismiss(upload.id)}
                        >
                          {labels.dismiss}
                        </button>
                      )}
                    </>
                  }
                />
              </li>
            ))}
          </ul>
        ),
      },
      timeout: finished ? 5000 : 0,
      onClose: () => {
        for (const upload of uploads) dismiss(upload.id);
      },
    });
  }, [uploads, finished, loading, labels, dismiss, add, close, id]);
  return null;
}

export function DriveTitle({
  name,
  onRename,
  disabled,
  labels,
}: {
  name: string;
  onRename?: (name: string) => Promise<void>;
  disabled: boolean;
  labels: DriveLabels;
}) {
  const [draft, setDraft] = useState<string>();
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();
  const input = useRef<HTMLInputElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const lock = useRef(false);
  const restoreFocus = useRef(false);
  const errorId = `factory-drive-title-error-${useId()}`;
  const editing = draft !== undefined;
  const { add } = Toast.useToastManager();
  useEffect(() => {
    if (editing) input.current?.select();
  }, [editing]);
  useEffect(() => {
    if (!editing && !disabled && restoreFocus.current) {
      trigger.current?.focus();
      restoreFocus.current = false;
    }
  }, [editing, disabled]);
  async function save(returnFocus: boolean) {
    if (disabled || lock.current || draft === undefined || !onRename) return;
    lock.current = true;
    setPending(true);
    setError(undefined);
    try {
      const next = validName(draft);
      if (next !== name) await onRename(next);
      restoreFocus.current = returnFocus;
      setDraft(undefined);
      setError(undefined);
    } catch (reason) {
      const message = messageFor(reason, labels);
      setError(message);
      add({ title: message, type: "error", data: { closeLabel: labels.close } });
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <h2
      className="relative min-w-0 font-medium"
      aria-current="page"
      aria-label={name}
      aria-busy={pending}
    >
      {onRename ? (
        <button
          ref={trigger}
          type="button"
          disabled={disabled}
          aria-label={`${labels.rename}: ${name}`}
          className={cn(
            buttonClass,
            "max-w-full justify-start px-0 text-left text-base wrap-anywhere",
            editing && "invisible",
          )}
          onClick={() => {
            setError(undefined);
            setDraft(name);
          }}
        >
          {name}
        </button>
      ) : (
        <span className="block py-1.5 wrap-anywhere">{name}</span>
      )}
      {editing && (
        <input
          ref={input}
          aria-label={labels.name}
          aria-invalid={!!error}
          aria-describedby={error ? errorId : undefined}
          value={draft}
          readOnly={disabled || pending || !onRename}
          className={cn(inputClass, "absolute inset-0 h-full px-0 font-medium md:text-base")}
          onChange={(event) => {
            setDraft(event.target.value);
            setError(undefined);
          }}
          onBlur={() => void save(false)}
          onKeyDown={(event) => {
            if (event.nativeEvent.isComposing) return;
            if (event.key === "Enter") {
              event.preventDefault();
              void save(true);
            } else if (event.key === "Escape" && !lock.current) {
              event.preventDefault();
              restoreFocus.current = true;
              setDraft(undefined);
              setError(undefined);
            }
          }}
        />
      )}
      {error && (
        <span id={errorId} className="sr-only">
          {error}
        </span>
      )}
    </h2>
  );
}

export function EntryDialog({
  client,
  scope,
  parentId,
  entry,
  space,
  onRenameSpace,
  deleting = false,
  trashing = false,
  duplicating = false,
  onClose,
  returnFocus,
  disabled = false,
  labels,
  refresh,
  children,
}: {
  client: DriveClient;
  scope: DriveScope;
  parentId: string | null;
  entry?: Pick<DriveEntry, "id" | "name">;
  space?: DriveSpace;
  onRenameSpace?: DriveBrowserProps["onRenameSpace"];
  deleting?: boolean;
  trashing?: boolean;
  duplicating?: boolean;
  /** A menu can mount an already open dialog without a second trigger. */
  onClose?: () => void;
  returnFocus?: RefObject<HTMLElement | null>;
  disabled?: boolean;
  labels: DriveLabels;
  refresh: () => void;
  children?: ReactNode;
}) {
  const [open, setOpen] = useState(!!onClose);
  const [name, setName] = useState(
    duplicating && entry ? labels.duplicateName(entry.name) : (entry?.name ?? space?.name ?? ""),
  );
  const [pending, setPending] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(!!onClose && deleting);
  const [error, setError] = useState<string>();
  const [preview, setPreview] = useState<DriveDeletePreview>();
  const previewRequest = useRef<Promise<DriveDeletePreview> | undefined>(undefined);
  const lock = useRef(false);
  const fieldId = `factory-drive-field-${useId()}`;
  const title = deleting
    ? trashing
      ? labels.trashTitle
      : labels.deleteTitle
    : duplicating
      ? labels.duplicate
      : entry || space
        ? labels.rename
        : labels.newFolder;
  function loadPreview() {
    if (disabled || !entry) return;
    setPreviewLoading(true);
    setError(undefined);
    setPreview(undefined);
    return startPreview();
  }
  function startPreview() {
    if (!entry) return;
    const request = Promise.resolve().then(() =>
      client.previewDelete({ scope, entryId: entry.id }),
    );
    previewRequest.current = request;
    void request.then(
      (result) => {
        if (previewRequest.current !== request) return;
        setPreview(result);
        setPreviewLoading(false);
      },
      (reason) => {
        if (previewRequest.current !== request) return;
        previewRequest.current = undefined;
        setError(messageFor(reason, labels));
        setPreviewLoading(false);
      },
    );
    return request;
  }
  useEffect(() => {
    // Menu dialogs mount open; ordinary triggers prepare the preview in changeOpen.
    if (onClose && deleting) void startPreview();
    return () => {
      previewRequest.current = undefined;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  async function submit() {
    if (disabled || lock.current) return;
    lock.current = true;
    setPending(true);
    setError(undefined);
    try {
      if (deleting && entry) {
        const confirmation = preview ?? (await (previewRequest.current ?? loadPreview()));
        if (!confirmation) return;
        if (trashing)
          await client.trashEntry!({ scope, entryId: entry.id, token: confirmation.token });
        else await client.deleteEntry({ scope, entryId: entry.id, token: confirmation.token });
      } else if (duplicating && entry)
        await client.duplicateEntry!({ scope, entryId: entry.id, name: validName(name) });
      else if (entry) await client.rename({ scope, entryId: entry.id, name: validName(name) });
      else if (space && onRenameSpace) await onRenameSpace(validName(name));
      else await client.createFolder({ scope, parentId, name: validName(name) });
      setOpen(false);
      refresh();
      onClose?.();
    } catch (reason) {
      setError(messageFor(reason, labels));
      if (deleting && errorCode(reason) === "CONFLICT") {
        setPreview(undefined);
        previewRequest.current = undefined;
      }
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  function changeOpen(next: boolean) {
    if (lock.current) return;
    setOpen(next);
    if (next) {
      setName(entry?.name ?? space?.name ?? "");
      setError(undefined);
      if (deleting) void loadPreview();
    } else {
      previewRequest.current = undefined;
      setPreviewLoading(false);
      onClose?.();
    }
  }
  return (
    <Dialog.Root open={open} onOpenChange={changeOpen}>
      {onClose ? null : (
        <IconTooltip label={entry ? (deleting ? labels.delete : labels.rename) : undefined}>
          <Dialog.Trigger
            disabled={disabled}
            className={cn(
              entry ? iconButtonClass : buttonClass,
              deleting &&
                "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
            )}
            aria-label={deleting ? labels.delete : entry ? labels.rename : labels.newFolder}
          >
            {children}
          </Dialog.Trigger>
        </IconTooltip>
      )}
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup
          finalFocus={returnFocus}
          onKeyDownCapture={deleting ? undefined : submitDialogOnShortcut}
          className={cn(
            cardClass,
            "fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 shadow-xl",
          )}
        >
          <Dialog.Title className="text-lg font-semibold">{title}</Dialog.Title>
          <Dialog.Description
            className={cn("text-sm text-muted-foreground", deleting && "min-h-20")}
          >
            {deleting
              ? preview && entry
                ? (trashing ? labels.trashDescription : labels.deleteDescription)(
                    entry.name,
                    preview.files,
                    preview.folders,
                  )
                : entry
                  ? (trashing ? labels.trashConfirmation : labels.deleteConfirmation)(entry.name)
                  : labels.loading
              : labels.nameHint}
          </Dialog.Description>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              void submit();
            }}
            className="space-y-4"
          >
            {!deleting && (
              <div className="space-y-2">
                <label htmlFor={fieldId} className="text-sm font-medium">
                  {labels.name}
                </label>
                <input
                  id={fieldId}
                  className={inputClass}
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  maxLength={255}
                  required
                  disabled={pending || disabled}
                />
              </div>
            )}
            <div className={deleting ? "min-h-5" : undefined}>
              <DriveFeedback
                message={
                  error ??
                  (deleting && (pending || previewLoading)
                    ? pending
                      ? labels.pending
                      : labels.loading
                    : undefined)
                }
                error={Boolean(error)}
              />
            </div>
            <div className="flex flex-wrap justify-end gap-2">
              <Dialog.Close className={outlineButtonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="submit"
                className={cn(
                  primaryClass,
                  deleting &&
                    "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                )}
                disabled={pending || disabled}
              >
                {pending && !deleting
                  ? labels.pending
                  : deleting
                    ? trashing
                      ? labels.moveToTrash
                      : labels.confirmDelete
                    : duplicating
                      ? labels.duplicate
                      : entry || space
                        ? labels.save
                        : labels.create}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import type { DriveTransfer } from "@/components/plugins/drive/transfer";
import { transferDriveUpload } from "@/components/plugins/drive/transfer";
import type { DriveClient, DriveScope } from "@/components/plugins/drive/types";
import { DriveError, errorCode, folderUploadPath } from "@/components/plugins/drive/utils";

type State =
  | "queued"
  | "uploading"
  | "finishing"
  | "done"
  | "failed"
  | "cancelled"
  | "cancelling"
  | "cancelFailed";
interface Job {
  id: string;
  file: File;
  parentId: string | null;
  relativePath?: string;
  state: State;
  progress: number;
  error?: unknown;
  controller: AbortController;
  reserved: boolean;
  busy: boolean;
  cancelled: boolean;
}
export function useUploads(
  client: DriveClient,
  scope: DriveScope,
  parentId: string | null,
  refresh: () => void,
  transfer: DriveTransfer = transferDriveUpload,
) {
  const jobs = useRef<Job[]>([]);
  const mounted = useRef(true);
  const [uploads, setUploads] = useState<Job[]>([]);
  const publish = useCallback(() => {
    if (mounted.current) setUploads(jobs.current.map((job) => ({ ...job })));
  }, []);
  const dismiss = useCallback(
    (id: string) => {
      jobs.current = jobs.current.filter(
        (job) => job.id !== id || !["done", "cancelled"].includes(job.state),
      );
      publish();
    },
    [publish],
  );
  async function abandon(job: Job) {
    job.state = "cancelling";
    publish();
    try {
      if (job.reserved) await client.cancelUpload({ scope, uploadId: job.id });
      job.state = "cancelled";
    } catch (error) {
      job.state = errorCode(error) === "NOT_FOUND" ? "cancelled" : "cancelFailed";
      job.error = job.state === "cancelled" ? undefined : error;
    }
    publish();
  }
  async function run(job: Job) {
    job.busy = true;
    job.state = "uploading";
    job.error = undefined;
    publish();
    try {
      if (job.relativePath !== undefined) {
        if (!client.prepareFolderUpload) throw new DriveError("INVALID");
        folderUploadPath(job.relativePath, job.file.name);
      }
      // Mark before preparation: a lost preparation response may still reserve a file.
      job.reserved = true;
      const input = {
        scope,
        parentId: job.parentId,
        requestId: job.id,
        name: job.file.name,
        size: job.file.size,
        contentType: job.file.type,
      };
      const ticket =
        job.relativePath !== undefined
          ? await client.prepareFolderUpload!({ ...input, relativePath: job.relativePath })
          : await client.prepareUpload(input);
      if (job.cancelled) {
        await abandon(job);
        return;
      }
      if (!ticket.completed) {
        try {
          await transfer(ticket, job.file, {
            signal: job.controller.signal,
            onProgress: (value) => {
              job.progress = value;
              publish();
            },
          });
        } catch (error) {
          if (job.cancelled) throw error;
          // A dropped PUT response is uncertain; the server can verify whether it arrived.
          job.state = "finishing";
          publish();
          await client.completeUpload({ scope, uploadId: job.id });
          job.state = "done";
          job.progress = 100;
          if (mounted.current) refresh();
          return;
        }
        if (job.cancelled) {
          await abandon(job);
          return;
        }
        job.state = "finishing";
        publish();
        await client.completeUpload({ scope, uploadId: job.id });
      }
      job.state = "done";
      job.progress = 100;
      if (mounted.current) refresh();
    } catch (error) {
      if (job.cancelled) await abandon(job);
      else {
        job.state = "failed";
        job.error = error;
      }
    } finally {
      job.busy = false;
      publish();
      pump();
    }
  }
  function pump() {
    if (!mounted.current) return;
    let active = jobs.current.filter((job) => job.busy).length;
    for (const job of jobs.current) {
      if (active >= 2) break;
      if (job.state === "queued") {
        active++;
        void run(job);
      }
    }
  }
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      for (const job of jobs.current) {
        if (["done", "cancelled"].includes(job.state)) continue;
        job.cancelled = true;
        job.controller.abort();
        if (!job.busy) void abandon(job);
      }
    };
    // This hook is owned by a browser keyed to its space and folder.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return {
    uploads,
    add(files: File[], maxBytes: number, destination = parentId, directory = false) {
      for (const file of files) {
        let error: unknown;
        try {
          if (file.size > maxBytes) throw new DriveError("INVALID");
          if (directory) {
            if (!client.prepareFolderUpload) throw new DriveError("INVALID");
            folderUploadPath(file.webkitRelativePath, file.name);
          }
        } catch (reason) {
          error = reason;
        }
        jobs.current.push({
          id: crypto.randomUUID(),
          file,
          parentId: destination,
          relativePath: directory ? file.webkitRelativePath : undefined,
          state: error ? "failed" : "queued",
          error,
          progress: 0,
          controller: new AbortController(),
          reserved: false,
          busy: false,
          cancelled: false,
        });
      }
      publish();
      pump();
    },
    cancel(id: string) {
      const job = jobs.current.find((item) => item.id === id);
      if (!job || job.state === "finishing" || job.state === "done") return;
      job.cancelled = true;
      job.controller.abort();
      if (!job.busy) void abandon(job);
      else {
        job.state = "cancelling";
        publish();
      }
    },
    retry(id: string) {
      const job = jobs.current.find((item) => item.id === id);
      if (!job || job.busy) return;
      if (job.state === "cancelFailed") {
        void abandon(job);
        return;
      }
      if (job.state !== "failed") return;
      job.controller = new AbortController();
      job.cancelled = false;
      job.state = "queued";
      job.progress = 0;
      publish();
      pump();
    },
    dismiss,
  };
}

import type { DriveScope, DriveSort, DriveSpace } from "@/components/plugins/drive/types";
export const DEFAULT_MAX_FILE_BYTES = 100_000_000;
export const scopeKey = (scope: DriveScope) => JSON.stringify([scope.type, scope.id]);
export type DriveErrorCode =
  | "INVALID"
  | "NOT_FOUND"
  | "FORBIDDEN"
  | "CONFLICT"
  | "RESTORE_CONFLICT"
  | "EXPIRED"
  | "DELETE_PENDING"
  | "DOWNLOAD_LIMIT"
  | "STORAGE";
export class DriveError extends Error {
  readonly code: DriveErrorCode;
  constructor(code: DriveErrorCode) {
    super(code);
    this.name = "DriveError";
    this.code = code;
  }
}
export function validName(input: string) {
  if (typeof input !== "string") throw new DriveError("INVALID");
  const name = input.trim();
  if (
    !name ||
    name.length > 255 ||
    name === "." ||
    name === ".." ||
    /[/\\]/.test(name) ||
    name.split("").some((char) => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127)
  )
    throw new DriveError("INVALID");
  return name;
}
export function validScope(scope: DriveScope) {
  if (
    !scope ||
    typeof scope.type !== "string" ||
    typeof scope.id !== "string" ||
    !scope.type.trim() ||
    !scope.id.trim() ||
    scope.type.length > 100 ||
    scope.id.length > 512
  )
    throw new DriveError("INVALID");
  return scope;
}
export function folderUploadPath(path: string, name: string) {
  if (typeof path !== "string" || path.length > 25_855) throw new DriveError("INVALID");
  const segments = path.split("/").map(validName);
  if (segments.length < 2 || segments.length > 101 || segments.at(-1) !== validName(name))
    throw new DriveError("INVALID");
  return segments;
}
export function validId(id: string) {
  if (
    typeof id !== "string" ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)
  )
    throw new DriveError("INVALID");
  return id;
}
export function errorCode(error: unknown): DriveErrorCode | undefined {
  if (
    error &&
    typeof error === "object" &&
    "code" in error &&
    typeof error.code === "string" &&
    [
      "INVALID",
      "NOT_FOUND",
      "FORBIDDEN",
      "CONFLICT",
      "RESTORE_CONFLICT",
      "EXPIRED",
      "DELETE_PENDING",
      "DOWNLOAD_LIMIT",
      "STORAGE",
    ].includes(error.code)
  )
    return error.code as DriveErrorCode;
}
export function safeDownloadUrl(input: string) {
  try {
    const url = new URL(input);
    return ["http:", "https:", "blob:"].includes(url.protocol) && !url.username && !url.password
      ? input
      : undefined;
  } catch {
    return undefined;
  }
}

export function validSort(sort: DriveSort = { field: "name", direction: "asc" }): DriveSort {
  if (
    !sort ||
    !["name", "updatedAt", "size", "owner"].includes(sort.field) ||
    !["asc", "desc"].includes(sort.direction)
  )
    throw new DriveError("INVALID");
  return sort;
}

/** Compare metadata before pagination; missing values sort last in either direction. */
export function compareDriveItems(
  a: Pick<DriveSpace, "name" | "updatedAt" | "size" | "owner">,
  b: Pick<DriveSpace, "name" | "updatedAt" | "size" | "owner">,
  sort: DriveSort,
) {
  const value = (item: typeof a) => {
    if (sort.field === "owner") return item.owner?.name;
    if (sort.field === "updatedAt") {
      const time = item.updatedAt ? Date.parse(item.updatedAt) : NaN;
      return Number.isFinite(time) ? time : undefined;
    }
    return item[sort.field];
  };
  const left = value(a);
  const right = value(b);
  if (left === undefined && right !== undefined) return 1;
  if (right === undefined && left !== undefined) return -1;
  const order =
    typeof left === "number" && typeof right === "number"
      ? left - right
      : String(left ?? "").localeCompare(String(right ?? ""));
  return order * (sort.direction === "asc" ? 1 : -1) || a.name.localeCompare(b.name);
}

"use client";

import { Dialog } from "@base-ui/react/dialog";
import { Toast } from "@base-ui/react/toast";
import { RefreshCwIcon, RotateCcwIcon, Trash2Icon } from "lucide-react";
import { useEffect, useId, useMemo, useRef, useState } from "react";

import { useActionToast } from "@/components/action-toast";
import { NativeSelect } from "@/components/native-select";
import type { DriveLabels } from "@/components/plugins/drive/labels";
import type {
  DriveClient,
  DriveFolderResult,
  DriveScope,
  DriveTrashEntry,
  DriveTrashResult,
} from "@/components/plugins/drive/types";
import {
  buttonClass,
  cardClass,
  DriveFeedback,
  DriveModified,
  EntryDialog,
  inputClass,
  messageFor,
  outlineButtonClass,
  primaryClass,
} from "@/components/plugins/drive/ui";
import { errorCode, validName } from "@/components/plugins/drive/utils";
import { TablePagination } from "@/components/table-pagination";
import { TableSearch } from "@/components/table-search";
import { cn } from "@/components/utils/cn";
