} from "@/components/utils/table-styles";
import { retainRemovedItems, useOptimisticAction } from "@/components/utils/use-optimistic-action";

export function TrashBrowser({
  client,
  scope,
  labels,
  locale,
  refreshKey = 0,
  onChanged,
}: {
  client: DriveClient;
  scope: DriveScope;
  labels: DriveLabels;
  locale?: string;
  refreshKey?: number;
  onChanged?: () => void;
}) {
  const [search, setSearch] = useState("");
  const [cursors, setCursors] = useState<string[]>([]);
  const cursor = cursors.at(-1);
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, scope, search, cursor, revision, refreshKey }),
    [client, scope, search, cursor, revision, refreshKey],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    data?: DriveTrashResult;
    error?: unknown;
    now?: number;
  }>();
  const [restoring, setRestoring] = useState<string>();
  const [restoreEntry, setRestoreEntry] = useState<DriveTrashEntry>();
  const lock = useRef(false);
  const manager = Toast.useToastManager();
  const notify = useActionToast();
  const loading = result?.request !== request;
  const mutationScope = useMemo(
    () => ({ client, scope, search, cursor }),
    [client, scope, search, cursor],
  );
  const optimistic = useOptimisticAction(result?.data, mutationScope);
  const data = optimistic.value;
  const error = loading ? undefined : result?.error;
  const disabled = loading || !!error || !!restoring || optimistic.pending;
  const refresh = () => setRevision((value) => value + 1);
  const restored = () => {
    setRestoreEntry(undefined);
    refresh();
    onChanged?.();
    notify(labels.restored);
  };
  useEffect(() => {
    const controller = new AbortController();
    void client.listTrash!({
      scope: request.scope,
      search: request.search,
      cursor: request.cursor,
      signal: controller.signal,
    })
      .then((data) => {
        if (!controller.signal.aborted) setResult({ request, data, now: Date.now() });
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) setResult({ request, error });
      });
    return () => controller.abort();
  }, [client, request]);
  async function restore(entry: DriveTrashEntry) {
    if (disabled || lock.current) return;
    lock.current = true;
    setRestoring(entry.id);
    try {
      await optimistic.run(
        (current) =>
          current && { ...current, items: current.items.filter((row) => row.id !== entry.id) },
        () => client.restoreEntry!({ scope, entryId: entry.id }),
      );
      restored();
    } catch (reason) {
      if (errorCode(reason) === "RESTORE_CONFLICT") setRestoreEntry(entry);
      else
        manager.add({
          title: messageFor(reason, labels),
          type: "error",
          data: { closeLabel: labels.close },
        });
    } finally {
      lock.current = false;
      setRestoring(undefined);
    }
  }
  return (
    <>
      <DriveFeedback
        message={optimistic.error ? messageFor(optimistic.error, labels) : undefined}
        error
      />
      <div className={tablePanelClass} aria-busy={loading}>
        <div className="mb-4 flex flex-wrap items-center justify-between gap-4">
          <p className="flex-1 basis-80 text-sm text-muted-foreground">{labels.trashHint}</p>
          <div className="ml-auto flex max-w-full flex-wrap justify-end gap-2">
            <TableSearch
              value={search}
              label={labels.searchTrash}
              clearLabel={labels.clearSearch}
              onValueChange={(value) => {
                setSearch(value);
                setCursors([]);
              }}
            />
            <button className={buttonClass} disabled={loading} onClick={refresh}>
              <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.retry}
            </button>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className={cn(tableClass, "min-w-[44rem]")} aria-label={labels.trash}>
            <thead>
              <tr className={tableRowClass}>
                {[
                  labels.name,
                  labels.originalLocation,
                  labels.deletedAt,
                  labels.expiresAt,
                  labels.actions,
                ].map((label, index) => (
                  <th
                    key={index}
                    scope="col"
                    className={index === 4 ? tableActionHeaderClass : tableHeaderClass}
                  >
                    {label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {(!!error || !data?.items.length) && (
                <tr>
                  <td colSpan={5} className={cn(tableCellClass, "py-8")}>
                    <DriveFeedback
                      message={
                        error
                          ? messageFor(error, labels)
                          : loading
                            ? labels.loading
                            : search
                              ? labels.noMatches
                              : labels.emptyTrash
                      }
                      error={!!error}
                    />
                  </td>
                </tr>
              )}
              {data &&
                retainRemovedItems(data.items, result?.data?.items ?? [], optimistic.pending).map(
                  (entry) => (
                    <tr
                      key={entry.id}
                      hidden={!data.items.some((row) => row.id === entry.id)}
                      className={tableRowClass}
                    >
                      <td className={cn(tableCellClass, "max-w-64 break-all")}>
                        {entry.name}
                        {entry.state === "deleting" && (
                          <output className="mt-1 block text-xs text-muted-foreground">
                            {labels.deleting}
                          </output>
                        )}
                      </td>
                      <td
                        className={cn(tableCellClass, "max-w-64 break-all text-muted-foreground")}
                      >
                        {entry.originalPath || labels.root}
                      </td>
                      <td className={cn(tableCellClass, "whitespace-nowrap text-muted-foreground")}>
                        <DriveModified
                          value={entry.deletedAt}
                          locale={locale}
                          fallback={labels.unavailable}
                        />
                      </td>
                      <td className={cn(tableCellClass, "whitespace-nowrap text-muted-foreground")}>
                        <DriveModified
                          value={entry.expiresAt}
                          locale={locale}
                          fallback={labels.unavailable}
                        />
                      </td>
                      <td className={tableActionCellClass}>
                        <div className={tableActionsClass}>
                          {data.space.capabilities.restore && entry.state === "trashed" && (
                            <button
                              className={buttonClass}
                              disabled={
                                disabled || Date.parse(entry.expiresAt) <= (result?.now ?? 0)
                              }
                              onClick={() => void restore(entry)}
                            >
                              <RotateCcwIcon aria-hidden="true" />
                              {restoring === entry.id ? labels.pending : labels.restore}
                            </button>
                          )}
                          {data.space.capabilities.delete && (
                            <EntryDialog
                              client={{
                                ...client,
                                deleteEntry: (input) =>
                                  optimistic.run(
                                    (current) =>
                                      current && {
                                        ...current,
                                        items: current.items.filter(
                                          (row) => row.id !== input.entryId,
                                        ),
                                      },
                                    () => client.deleteEntry(input),
                                  ),
                              }}
                              scope={scope}
                              parentId={null}
                              entry={entry}
                              deleting
                              disabled={disabled}
                              labels={labels}
                              refresh={() => {
                                refresh();
                                notify(labels.deleted);
                              }}
                            >
                              <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
                            </EntryDialog>
                          )}
                        </div>
                      </td>
                    </tr>
                  ),
                )}
            </tbody>
          </table>
        </div>
        <TablePagination
          label={labels.title}
          page={cursors.length + 1}
          previousLabel={labels.previous}
          nextLabel={labels.next}
          previousDisabled={cursors.length === 0}
          nextDisabled={!!error || !data?.nextCursor}
          disabled={loading}
          onPrevious={() => setCursors(cursors.slice(0, -1))}
          onNext={() => {
            if (data?.nextCursor) setCursors([...cursors, data.nextCursor]);
          }}
        />
      </div>
      {restoreEntry && (
        <RestoreDialog
          client={client}
          scope={scope}
          entry={restoreEntry}
          labels={labels}
          canRename={!!data?.space.capabilities.rename}
          disabled={disabled}
          close={() => setRestoreEntry(undefined)}
          restored={restored}
          onRestore={(input) =>
            optimistic.run(
              (current) =>
                current && {
                  ...current,
                  items: current.items.filter((row) => row.id !== input.entryId),
                },
              () => client.restoreEntry!(input),
            )
          }
        />
      )}
    </>
  );
}

function RestoreDialog({
  client,
  scope,
  entry,
  labels,
  canRename,
  disabled,
  close,
  restored,
  onRestore,
}: {
  client: DriveClient;
  scope: DriveScope;
  entry: DriveTrashEntry;
  labels: DriveLabels;
  canRename: boolean;
  disabled: boolean;
  close: () => void;
  restored: () => void;
  onRestore: NonNullable<DriveClient["restoreEntry"]>;
}) {
  const [name, setName] = useState(entry.name);
  const [destination, setDestination] = useState<string | null>();
  const [cursors, setCursors] = useState<string[]>([]);
  const cursor = cursors.at(-1);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>(labels.RESTORE_CONFLICT);
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, scope, destination, cursor, revision }),
    [client, scope, destination, cursor, revision],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    data?: DriveFolderResult;
    error?: string;
  }>();
  const folder = result?.data;
  const loading = result?.request !== request;
  const folderError = loading ? undefined : result?.error;
  const lock = useRef(false);
  const fieldId = `factory-drive-restore-${useId()}`;
  useEffect(() => {
    const controller = new AbortController();
    void client
      .listEntries({ scope, parentId: destination ?? null, cursor, signal: controller.signal })
      .then((data) => {
        if (!controller.signal.aborted) {
          setResult({ request, data });
        }
      })
      .catch((reason: unknown) => {
        if (!controller.signal.aborted) {
          setResult({ request, error: messageFor(reason, labels) });
        }
      });
    return () => controller.abort();
  }, [client, scope, destination, cursor, request, labels]);
  async function submit() {
    if (disabled || lock.current) return;
    lock.current = true;
    setPending(true);
    setError("");
    try {
      await onRestore({
        scope,
        entryId: entry.id,
        parentId: destination,
        name: validName(name),
      });
      restored();
    } catch (reason) {
      setError(messageFor(reason, labels));
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !lock.current) close();
      }}
    >
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup
          onKeyDownCapture={submitDialogOnShortcut}
          className={cn(
            cardClass,
            "fixed top-1/2 left-1/2 z-50 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 overflow-y-auto shadow-xl",
          )}
        >
          <Dialog.Title className="text-lg font-semibold">{labels.restoreTitle}</Dialog.Title>
          <Dialog.Description className="text-sm text-muted-foreground">
            {labels.restoreDescription}
          </Dialog.Description>
          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              void submit();
            }}
          >
            <div className="space-y-2">
              <label htmlFor={fieldId} className="text-sm font-medium">
                {labels.name}
              </label>
              <input
                id={fieldId}
                className={inputClass}
                value={name}
                onChange={(event) => setName(event.target.value)}
                required
                maxLength={255}
                disabled={pending || disabled || !canRename}
              />
            </div>
            <div className="space-y-2">
              <label htmlFor={`${fieldId}-folder`} className="text-sm font-medium">
                {labels.destination}
              </label>
              <NativeSelect
                id={`${fieldId}-folder`}
                className={inputClass}
                value={destination === undefined ? "original" : (destination ?? "root")}
                disabled={pending || disabled || loading}
                onChange={(event) => {
                  setDestination(
                    event.target.value === "original"
                      ? undefined
                      : event.target.value === "root"
                        ? null
                        : event.target.value,
                  );
                  setCursors([]);
                }}
              >
                <option value="original">
                  {labels.originalFolder}: {entry.originalPath || labels.root}
                </option>
                <option value="root">{labels.root}</option>
                {folder?.breadcrumbs.map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.name}
                  </option>
                ))}
                {folder?.items
                  .filter((row) => row.kind === "folder" && row.state === "ready")
                  .map((row) => (
                    <option key={row.id} value={row.id}>
                      {row.name}
                    </option>
                  ))}
              </NativeSelect>
              <div className="min-h-10">
                <DriveFeedback
                  message={loading ? labels.loading : folderError}
                  error={!!folderError}
                />
              </div>
              <div className="flex flex-wrap gap-2">
                <TablePagination
                  className="mt-0"
                  label={labels.destination}
                  page={cursors.length + 1}
                  previousLabel={labels.previous}
                  nextLabel={labels.next}
                  previousDisabled={cursors.length === 0}
                  nextDisabled={!folder?.nextCursor || !!folderError}
                  disabled={loading || pending}
                  onPrevious={() => setCursors(cursors.slice(0, -1))}
                  onNext={() => {
                    if (folder?.nextCursor) setCursors([...cursors, folder.nextCursor]);
                  }}
                />
                {folderError && (
                  <button
                    type="button"
                    className={buttonClass}
                    onClick={() => setRevision((value) => value + 1)}
                  >
                    <RefreshCwIcon aria-hidden="true" />
                    {labels.retry}
                  </button>
                )}
              </div>
            </div>
            <div className="min-h-15 md:min-h-10">
              <DriveFeedback message={error} error />
            </div>
            <div className="flex flex-wrap justify-end gap-2">
              <Dialog.Close className={outlineButtonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="submit"
                className={primaryClass}
                disabled={pending || disabled || loading || !!folderError}
              >
                {pending ? labels.pending : labels.restore}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";

import { Collapsible } from "@base-ui/react/collapsible";
import { ChevronRightIcon, RefreshCwIcon } from "lucide-react";
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

import { IconTooltip } from "@/components/icon-tooltip";
import type { DriveLabels } from "@/components/plugins/drive/labels";
import type {
  DriveBrowserProps,
  DriveEntry,
  DriveFolderResult,
} from "@/components/plugins/drive/types";
import { DriveFeedback, DriveFolderIcon, messageFor } from "@/components/plugins/drive/ui";
import { errorCode } from "@/components/plugins/drive/utils";
import { sidebarNavActiveClass, sidebarNavItemClass } from "@/components/sidebar-navigation";
import { cn } from "@/components/utils/cn";

type FolderTreeProps = Pick<DriveBrowserProps, "client" | "scope" | "getFolderHref"> & {
  parentId: string | null;
  currentFolderId: string | null;
  breadcrumbs: DriveFolderResult["breadcrumbs"];
  labels: DriveLabels;
  linkComponent: NonNullable<DriveBrowserProps["linkComponent"]>;
  onNavigate: () => void;
  onLoadingChange: (loading: boolean) => void;
  refreshKey: number;
  filesActive: boolean;
  renderActions: (entry: DriveEntry, disabled: boolean) => ReactNode;
};

export function DriveFolderTree(props: FolderTreeProps) {
  const { client, scope, parentId, labels, refreshKey, onLoadingChange } = props;
  const [page, setPage] = useState<{ refreshKey: number; cursor?: string }>({ refreshKey });
  if (page.refreshKey !== refreshKey) setPage({ refreshKey });
  const cursor = page.refreshKey === refreshKey ? page.cursor : undefined;
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, scope, parentId, cursor, revision, refreshKey }),
    [client, scope, parentId, cursor, revision, refreshKey],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    entries: DriveEntry[];
    nextCursor?: string;
    error?: unknown;
  }>();
  const loading = result?.request !== request;
  useEffect(() => onLoadingChange(loading), [loading, onLoadingChange]);
  const error = loading ? undefined : result?.error;
  const nextCursor = result?.nextCursor;
  const lock = useRef(false);
  const entries = result?.entries ?? [];
  const parentIndex = props.breadcrumbs.findIndex((crumb) => crumb.id === parentId);
  const ancestor =
    parentId === null
      ? props.breadcrumbs[0]
      : parentIndex >= 0
        ? props.breadcrumbs[parentIndex + 1]
        : undefined;
  const visibleEntries =
    !error && ancestor && !entries.some((entry) => entry.id === ancestor.id)
      ? [...entries, ancestor]
      : entries;

  useEffect(() => {
    const controller = new AbortController();
    void client
      .listEntries({ scope, parentId, cursor, signal: controller.signal })
      .then((data) => {
        if (controller.signal.aborted) return;
        const folders = data.items.filter(
          (entry) => entry.kind === "folder" && entry.state === "ready",
        );
        setResult((previous) => ({
          request,
          entries: cursor
            ? [
                ...(previous?.entries ?? []),
                ...folders.filter((entry) => !previous?.entries.some((old) => old.id === entry.id)),
              ]
            : folders,
          nextCursor: data.nextCursor,
        }));
      })
      .catch((reason: unknown) => {
        if (controller.signal.aborted) return;
        setResult((previous) => ({
          request,
          error: reason,
          entries: ["FORBIDDEN", "NOT_FOUND"].includes(errorCode(reason) ?? "")
            ? []
            : (previous?.entries ?? []),
        }));
      })
      .finally(() => {
        if (!controller.signal.aborted) lock.current = false;
      });
    return () => controller.abort();
  }, [client, scope, parentId, cursor, request]);

  return (
    <div aria-busy={loading}>
      <ul className="space-y-0.5">
        {visibleEntries.map((entry) => (
          <FolderNode key={entry.id} {...props} entry={entry} disabled={loading || !!error} />
        ))}
      </ul>
      {loading && (
        <div className="sr-only">
          <DriveFeedback message={labels.loading} />
        </div>
      )}
      {(!!error || !!nextCursor) && (
        <div className="flex h-10 items-center gap-1 px-2 md:h-8">
          {error ? (
            <>
              <p role="alert" className="min-w-0 flex-1 truncate text-sm text-destructive">
                {messageFor(error, labels)}
              </p>
              <IconTooltip label={`${messageFor(error, labels)} ${labels.retry}`}>
                <button
                  type="button"
                  aria-label={`${messageFor(error, labels)} ${labels.retry}`}
                  className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-lg outline-none hover:bg-sidebar-accent focus-visible:ring-2 focus-visible:ring-sidebar-ring md:size-8"
                  onClick={() => setRevision((value) => value + 1)}
                >
                  <RefreshCwIcon className="size-4" aria-hidden="true" />
                </button>
              </IconTooltip>
            </>
          ) : nextCursor ? (
            <button
              type="button"
              className={sidebarNavItemClass}
              disabled={loading}
              onClick={() => {
                if (loading || lock.current) return;
                lock.current = true;
                setPage({ refreshKey, cursor: nextCursor });
              }}
            >
              <span className="truncate">{labels.loadMoreFolders}</span>
            </button>
          ) : null}
        </div>
      )}
    </div>
  );
}

function FolderNode({
  entry,
  disabled,
  ...props
}: FolderTreeProps & {
  entry: DriveEntry | DriveFolderResult["breadcrumbs"][number];
  disabled: boolean;
}) {
  const {
    currentFolderId,
    breadcrumbs,
    filesActive,
    labels,
    getFolderHref,
    linkComponent: HostLink,
    onNavigate,
  } = props;
  const active =
    filesActive &&
    (entry.id === currentFolderId || breadcrumbs.some((crumb) => crumb.id === entry.id));
  const [expansion, setExpansion] = useState({ active, open: active });
  if (expansion.active !== active) setExpansion({ active, open: expansion.open || active });
  const open = expansion.open;
  const [loading, setLoading] = useState(true);
  const toggleLabel = `${open ? labels.collapseFolder : labels.expandFolder}: ${entry.name}`;
  return (
    <li>
      <Collapsible.Root open={open} onOpenChange={(open) => setExpansion({ active, open })}>
        <div className="group/drive-folder-row flex items-center gap-1">
          <IconTooltip label={toggleLabel}>
            <Collapsible.Trigger
              aria-label={toggleLabel}
              className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-lg outline-none hover:bg-sidebar-accent focus-visible:ring-2 focus-visible:ring-sidebar-ring md:size-8"
            >
              <ChevronRightIcon
                className={cn(
                  "size-4 transition-transform motion-reduce:transition-none",
                  open && "rotate-90",
                )}
                aria-hidden="true"
              />
            </Collapsible.Trigger>
          </IconTooltip>
          <HostLink
            href={getFolderHref(entry.id)}
            aria-label={`${labels.folder}: ${entry.name}`}
            aria-current={filesActive && entry.id === currentFolderId ? "page" : undefined}
            className={cn(
              sidebarNavItemClass,
              "group/drive-folder min-w-0 flex-1",
              active && sidebarNavActiveClass,
            )}
            onClick={(event) => {
              if (
                !event.defaultPrevented &&
                event.button === 0 &&
                !event.metaKey &&
                !event.ctrlKey &&
                !event.shiftKey &&
                !event.altKey
              )
                onNavigate();
            }}
          >
            <DriveFolderIcon open={open || active} loading={open && loading} />
            <span className="min-w-0 wrap-anywhere">{entry.name}</span>
          </HostLink>
          {"kind" in entry && props.renderActions(entry, disabled)}
        </div>
        <Collapsible.Panel>
          <div className="ml-4 border-l border-sidebar-border pl-2">
            {open && (
              <DriveFolderTree {...props} parentId={entry.id} onLoadingChange={setLoading} />
            )}
          </div>
        </Collapsible.Panel>
      </Collapsible.Root>
    </li>
  );
}

"use client";

import {
  CopyIcon,
  DownloadIcon,
  FolderPlusIcon,
  EllipsisVerticalIcon,
  PencilIcon,
  PlusIcon,
  Trash2Icon,
  UploadIcon,
  FolderUpIcon,
} from "lucide-react";
import { useRef } from "react";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/dropdown-menu";
import { IconTooltip } from "@/components/icon-tooltip";
import type { DriveLabels } from "@/components/plugins/drive/labels";
import type {
  DriveCapabilities,
  DriveClient,
  DriveEntry,
  DriveSpace,
} from "@/components/plugins/drive/types";
import { buttonClass } from "@/components/plugins/drive/ui";
import { cn } from "@/components/utils/cn";

export interface DriveFolderMenuProps {
  entry: DriveEntry | DriveSpace;
  capabilities?: DriveCapabilities;
  client: DriveClient;
  trashEnabled: boolean;
  disabled: boolean;
  downloading: boolean;
  labels: DriveLabels;
  onUpload: (entry: DriveEntry | DriveSpace, directory: boolean) => void;
  onDownload: (entry: DriveEntry | DriveSpace) => void;
  onAction: (
    entry: DriveEntry | DriveSpace,
    action: "create" | "rename" | "duplicate" | "trash",
    trigger: HTMLButtonElement | null,
  ) => void;
}

export function DriveFolderMenu({
  entry,
  capabilities,
  client,
  trashEnabled,
  disabled,
  downloading,
  labels,
  onUpload,
  onDownload,
  onAction,
}: DriveFolderMenuProps) {
  const trigger = useRef<HTMLButtonElement>(null);
  const duplicate =
    "kind" in entry &&
    !!client.duplicateEntry &&
    capabilities?.download &&
    capabilities.upload &&
    capabilities.createFolder;
  const trash = "kind" in entry && trashEnabled && capabilities?.delete;
  if (
    !capabilities ||
    (!capabilities.upload &&
      !capabilities.createFolder &&
      !capabilities.rename &&
      !capabilities.download &&
      !duplicate &&
      !trash)
  )
    return null;
  const label = `${labels.actions}: ${entry.name}`;
  const itemClass = "min-h-10 rounded-md md:min-h-8";
  return (
    <DropdownMenu>
      <IconTooltip label={label}>
        <DropdownMenuTrigger
          ref={trigger}
          disabled={disabled}
          aria-label={label}
          className={cn(buttonClass, "group/drive-folder-menu size-10 shrink-0 p-0 md:size-8")}
        >
          <EllipsisVerticalIcon
            className={cn(
              "size-4 shrink-0",
              "kind" in entry &&
                "group-focus-within/drive-folder-row:opacity-100 group-hover/drive-folder-row:opacity-100 group-data-popup-open/drive-folder-menu:opacity-100 [@media(hover:hover)_and_(pointer:fine)]:opacity-0",
            )}
            aria-hidden="true"
          />
        </DropdownMenuTrigger>
      </IconTooltip>
      <DropdownMenuContent align="end" className="min-w-52 rounded-xl motion-reduce:animate-none">
        <p className="max-w-64 truncate px-2 py-2 text-sm font-semibold">{entry.name}</p>
        <DropdownMenuSeparator />
        {(capabilities.upload || capabilities.createFolder) && (
          <DropdownMenuSub>
            <DropdownMenuSubTrigger className={itemClass}>
              <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.add}
            </DropdownMenuSubTrigger>
            <DropdownMenuSubContent className="min-w-48 rounded-xl motion-reduce:animate-none">
              {capabilities.upload && (
                <DropdownMenuItem className={itemClass} onClick={() => onUpload(entry, false)}>
                  <UploadIcon className="size-4 shrink-0" aria-hidden="true" />
                  {labels.uploadFile}
                </DropdownMenuItem>
              )}
              {capabilities.upload && capabilities.createFolder && client.prepareFolderUpload && (
                <DropdownMenuItem className={itemClass} onClick={() => onUpload(entry, true)}>
                  <FolderUpIcon className="size-4 shrink-0" aria-hidden="true" />
                  {labels.uploadFolder}
                </DropdownMenuItem>
              )}
              {capabilities.createFolder && (
                <>
                  {capabilities.upload && <DropdownMenuSeparator />}
                  <DropdownMenuItem
                    className={itemClass}
                    onClick={() => onAction(entry, "create", trigger.current)}
                  >
                    <FolderPlusIcon className="size-4 shrink-0" aria-hidden="true" />
                    {labels.folder}
                  </DropdownMenuItem>
                </>
              )}
            </DropdownMenuSubContent>
          </DropdownMenuSub>
        )}
        {capabilities?.rename && (
          <DropdownMenuItem
            className={itemClass}
            onClick={() => onAction(entry, "rename", trigger.current)}
          >
            <PencilIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.rename}
          </DropdownMenuItem>
        )}
        {duplicate && (
          <DropdownMenuItem
            className={itemClass}
            onClick={() => onAction(entry, "duplicate", trigger.current)}
          >
            <CopyIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.duplicate}
          </DropdownMenuItem>
        )}
        {capabilities.download && (
          <DropdownMenuItem
            className={itemClass}
            disabled={downloading}
            onClick={() => onDownload(entry)}
          >
            <DownloadIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.download}
          </DropdownMenuItem>
        )}
        {trash && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              variant="destructive"
              className={itemClass}
              onClick={() => onAction(entry, "trash", trigger.current)}
            >
              <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
              {labels.moveToTrash}
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { zipSync } from "fflate";

import type {
  DriveClient,
  DriveEntry,
  DriveScope,
  DriveSpace,
} from "@/components/plugins/drive/types";
import { DriveError, safeDownloadUrl, validName } from "@/components/plugins/drive/utils";

// shortcut: browser ZIPs hold bytes in memory; use server streaming for larger archives.
const MAX_BYTES = 100_000_000;
const MAX_ENTRIES = 1000;

export async function downloadFolder(
  client: DriveClient,
  scope: DriveScope,
  folder: DriveEntry | DriveSpace,
  signal: AbortSignal,
): Promise<Blob> {
  const files: Record<string, Uint8Array> = Object.create(null);
  const pending: { entry: DriveEntry; path: string }[] = [];
  const visited = new Set<string | null>();
  let expectedBytes = 0;
  let receivedBytes = 0;

  async function collect(entry: DriveEntry | DriveSpace, prefix: string, depth: number) {
    signal.throwIfAborted();
    const id = "kind" in entry ? entry.id : null;
    if (("kind" in entry && entry.state !== "ready") || visited.has(id))
      throw new DriveError("CONFLICT");
    if (entry.name !== validName(entry.name)) throw new DriveError("INVALID");
    visited.add(id);
    if (visited.size > MAX_ENTRIES || depth > 100) throw new DriveError("DOWNLOAD_LIMIT");
    const isFile = "kind" in entry && entry.kind === "file";
    const path = `${prefix}${entry.name}${isFile ? "" : "/"}`;
    if (Object.hasOwn(files, path)) throw new DriveError("CONFLICT");
    files[path] = new Uint8Array();
    if (isFile) {
      if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw new DriveError("INVALID");
      expectedBytes += entry.size;
      if (expectedBytes > MAX_BYTES) throw new DriveError("DOWNLOAD_LIMIT");
      pending.push({ entry, path });
      return;
    }
    let cursor: string | undefined;
    const cursors = new Set<string>();
    do {
      const page = await client.listEntries({ scope, parentId: id, cursor, signal });
      if (!page.space.capabilities.download) throw new DriveError("FORBIDDEN");
      for (const child of page.items) {
        if (child.parentId !== id) throw new DriveError("CONFLICT");
        await collect(child, path, depth + 1);
      }
      cursor = page.nextCursor;
      if (cursor && cursors.has(cursor)) throw new DriveError("CONFLICT");
      if (cursor) cursors.add(cursor);
    } while (cursor);
  }

  if ("kind" in folder && folder.kind !== "folder") throw new DriveError("INVALID");
  await collect(folder, "", 0);
  for (const { entry, path } of pending) {
    signal.throwIfAborted();
    const result = await client.getDownload({ scope, entryId: entry.id });
    const url = safeDownloadUrl(result.url);
    if (!url) throw new DriveError("INVALID");
    const response = await fetch(url, { signal, credentials: "omit" });
    if (!response.ok || !response.body) throw new DriveError("STORAGE");
    const reader = response.body.getReader();
    const chunks: Uint8Array[] = [];
    let size = 0;
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        size += value.byteLength;
        receivedBytes += value.byteLength;
        if (receivedBytes > MAX_BYTES) throw new DriveError("DOWNLOAD_LIMIT");
        chunks.push(value);
      }
    } finally {
      await reader.cancel().catch(() => undefined);
      reader.releaseLock();
    }
    const bytes = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) {
      bytes.set(chunk, offset);
      offset += chunk.byteLength;
    }
    files[path] = bytes;
  }
  signal.throwIfAborted();
  return new Blob([zipSync(files, { level: 0 })], { type: "application/zip" });
}
